{
  "topics": [
    {
      "id": "one-dimensional-kinematics",
      "title": "One-Dimensional Kinematics",
      "summary": "Students learn to describe and analyze motion along a straight line using position, velocity, acceleration, kinematic equations, free-fall motion, and calculus integration.",
      "concepts": [
        {
          "id": "position-displacement-velocity",
          "name": "Position, Displacement, and Average Velocity",
          "description": "Students can calculate displacement, average speed, and average velocity for straight-line motion.",
          "prerequisites": []
        },
        {
          "id": "instantaneous-velocity-speed",
          "name": "Instantaneous Velocity and Speed",
          "description": "Students can determine instantaneous velocity and speed using position-time graphs and differential calculus.",
          "prerequisites": [
            "position-displacement-velocity"
          ]
        },
        {
          "id": "acceleration",
          "name": "Average and Instantaneous Acceleration",
          "description": "Students can calculate average acceleration and derive instantaneous acceleration from velocity-time data or functions.",
          "prerequisites": [
            "instantaneous-velocity-speed"
          ]
        },
        {
          "id": "constant-acceleration-kinematics",
          "name": "Kinematic Equations for Constant Acceleration",
          "description": "Students can apply 1D kinematic equations to solve for unknown motion variables under uniform acceleration.",
          "prerequisites": [
            "acceleration"
          ]
        },
        {
          "id": "free-fall-motion",
          "name": "Free-Fall Motion",
          "description": "Students can solve vertical motion problems for objects moving solely under the influence of gravity.",
          "prerequisites": [
            "constant-acceleration-kinematics"
          ]
        },
        {
          "id": "integration-kinematics",
          "name": "Kinematics via Integration",
          "description": "Students can integrate time-dependent acceleration or velocity functions to derive velocity and displacement equations.",
          "prerequisites": [
            "acceleration"
          ]
        }
      ]
    },
    {
      "id": "newtons-laws-of-motion",
      "title": "Newton's Laws of Motion",
      "summary": "Students explore the fundamental principles governing force, mass, equilibrium, and dynamics in physical systems.",
      "concepts": [
        {
          "id": "force-and-free-body-diagrams",
          "name": "Forces and Free-Body Diagrams",
          "description": "Students can identify forces and draw accurate free-body diagrams representing all external forces acting on a body.",
          "prerequisites": []
        },
        {
          "id": "newtons-first-law",
          "name": "Newton's First Law and Inertia",
          "description": "Students can explain inertia, define inertial reference frames, and apply equilibrium conditions when net force is zero.",
          "prerequisites": [
            "force-and-free-body-diagrams"
          ]
        },
        {
          "id": "newtons-second-law",
          "name": "Newton's Second Law",
          "description": "Students can express Newton's second law in vector and component forms to determine system acceleration from net forces.",
          "prerequisites": [
            "force-and-free-body-diagrams",
            "constant-acceleration-kinematics"
          ]
        },
        {
          "id": "mass-and-weight",
          "name": "Mass and Weight",
          "description": "Students can differentiate between mass and gravitational weight and calculate gravitational force components.",
          "prerequisites": [
            "newtons-second-law"
          ]
        },
        {
          "id": "newtons-third-law",
          "name": "Newton's Third Law",
          "description": "Students can identify interaction pairs of forces acting between contacting or interacting objects.",
          "prerequisites": [
            "force-and-free-body-diagrams"
          ]
        }
      ]
    },
    {
      "id": "applications-of-newtons-laws",
      "title": "Applications of Newton's Laws",
      "summary": "Students apply dynamics principles to analyze complex physical situations involving friction, coupled bodies, circular motion, and drag forces.",
      "concepts": [
        {
          "id": "multi-body-dynamics",
          "name": "Multi-Body Systems and Coupled Motion",
          "description": "Students can solve dynamics problems for multi-body systems, such as Atwood machines and connected blocks on inclines.",
          "prerequisites": [
            "newtons-second-law",
            "newtons-third-law"
          ]
        },
        {
          "id": "friction-forces",
          "name": "Static and Kinetic Friction",
          "description": "Students can calculate static and kinetic resistive forces operating on surfaces using friction coefficients.",
          "prerequisites": [
            "newtons-second-law",
            "mass-and-weight"
          ]
        },
        {
          "id": "centripetal-force",
          "name": "Centripetal Force and Banked Curves",
          "description": "Students can analyze uniform circular motion and calculate centripetal forces required for objects on curved paths and banked roads.",
          "prerequisites": [
            "newtons-second-law"
          ]
        },
        {
          "id": "drag-force-and-terminal-velocity",
          "name": "Drag Force and Terminal Velocity",
          "description": "Students can calculate fluid drag forces and determine the terminal speed of an object falling through a fluid.",
          "prerequisites": [
            "newtons-second-law",
            "free-fall-motion"
          ]
        }
      ]
    },
    {
      "id": "work-and-kinetic-energy",
      "title": "Work and Kinetic Energy",
      "summary": "Students study energy transfer through work done by constant and variable forces, kinetic energy, the work-energy theorem, and power.",
      "concepts": [
        {
          "id": "work-by-constant-force",
          "name": "Work Done by a Constant Force",
          "description": "Students can compute mechanical work performed by constant forces using dot products and force-displacement geometry.",
          "prerequisites": [
            "force-and-free-body-diagrams"
          ]
        },
        {
          "id": "work-by-variable-force",
          "name": "Work Done by Variable Forces",
          "description": "Students can calculate work done by position-varying forces, such as springs, using calculus integrals and graphical areas.",
          "prerequisites": [
            "work-by-constant-force"
          ]
        },
        {
          "id": "work-energy-theorem",
          "name": "Work-Energy Theorem",
          "description": "Students can apply the work-energy theorem to relate total net work on an object to changes in its kinetic energy.",
          "prerequisites": [
            "work-by-constant-force",
            "constant-acceleration-kinematics"
          ]
        },
        {
          "id": "power",
          "name": "Power",
          "description": "Students can calculate average and instantaneous rate of work done by mechanical forces.",
          "prerequisites": [
            "work-by-constant-force"
          ]
        }
      ]
    }
  ]
}
